arguments.new_str:
using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// --- Tools ---
var notebook = new ResearchNotebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync,
        name: "search_web",
        description: "Search the web for information on a query. Returns a list of result titles, URLs, and snippets."),
    AIFunctionFactory.Create(notebook.AddNote,
        name: "add_note",
        description: "Save a research note with a title and body for later reference."),
    AIFunctionFactory.Create(notebook.GetNotes,
        name: "get_notes",
        description: "Retrieve all saved research notes."),
};

// --- Chat Client ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Agent ---
const string instructions = """
    You are a research agent. When given a topic:
    1. Search the web with multiple varied queries to gather diverse information.
    2. Save key findings as notes using the add_note tool.
    3. After gathering enough information, retrieve your notes and write a
       comprehensive summary with key findings, different perspectives, and sources.
    Always cite your sources with URLs.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

// --- Run ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions))
{
    if (update.Role == ChatRole.Assistant)
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

/// <summary>Simulates web search using Bing search via scraping.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
        },
    };

    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var html = await s_http.GetStringAsync(
                $"https://html.duckduckgo.com/html/?q={encoded}");

            var results = ParseResults(html);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();
            foreach (var r in results.Take(5))
            {
                sb.AppendLine($"**{r.Title}**");
                sb.AppendLine($"  URL: {r.Url}");
                sb.AppendLine($"  {r.Snippet}");
                sb.AppendLine();
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        // Parse DuckDuckGo HTML results — each result lives in a <div class="result">
        const string resultMarker = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (pos < span.Length && results.Count < 5)
        {
            int linkStart = html.IndexOf(resultMarker, pos, StringComparison.Ordinal);
            if (linkStart < 0) break;

            // Extract href
            int hrefStart = html.LastIndexOf("href=\"", linkStart, Math.Min(linkStart, 200), StringComparison.Ordinal);
            string url = "";
            string title = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                int hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    url = WebUtility.HtmlDecode(html[hrefStart..hrefEnd]);
            }

            // Extract title (text inside the <a> tag)
            int tagClose = html.IndexOf('>', linkStart);
            if (tagClose >= 0)
            {
                int titleEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
                if (titleEnd > tagClose)
